import socket,struct,json,time,pathlib
results={'resolv_conf':pathlib.Path('/etc/resolv.conf').read_text(),'queries':[]}
resolver='172.31.0.93'
for name in ['example.com','pypi.org']:
 for qtype in [1,28]:
  query=struct.pack('!HHHHHH',12345,256,1,0,0,0)+b''.join(bytes([len(s)])+s.encode() for s in name.split('.'))+b'\0'+struct.pack('!HH',qtype,1)
  for transport in ['udp','tcp']:
   start=time.monotonic(); row={'name':name,'type':qtype,'transport':transport,'resolver':resolver}
   try:
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM if transport=='udp' else socket.SOCK_STREAM) as sock:
     sock.settimeout(2)
     if transport=='udp':
      sock.sendto(query,(resolver,53)); data,peer=sock.recvfrom(4096)
     else:
      sock.connect((resolver,53)); sock.sendall(struct.pack('!H',len(query))+query); data=sock.recv(4096)[2:]
     fields=struct.unpack('!HHHHHH',data[:12]);row.update(rcode=fields[1]&15,answers=fields[3],bytes=len(data))
   except Exception as e: row.update(error=type(e).__name__,message=str(e))
   row['elapsed_seconds']=round(time.monotonic()-start,3);results['queries'].append(row)
for name in ['localhost','example.com','pypi.org']:
 try: results.setdefault('getaddrinfo',{})[name]=sorted({r[4][0] for r in socket.getaddrinfo(name,443)})
 except Exception as e:results.setdefault('getaddrinfo',{})[name]={'error':type(e).__name__,'message':str(e)}
print(json.dumps(results,indent=2))

